  function shopRows(a){let rows=baseShopRows(a),q=state.shopSearch.trim().toLowerCase();if(q)rows=rows.filter(r=>(shopName(r)+' '+shopLocation(r)+' '+JSON.stringify(r)).toLowerCase().includes(q));if(state.shopSort==='gross')rows.sort((x,y)=>shopGross(y)-shopGross(x));if(state.shopSort==='low')rows.sort((x,y)=>shopGross(x)-shopGross(y));if(state.shopSort==='net')rows.sort((x,y)=>shopNet(y)-shopNet(x));if(state.shopSort==='grade'){const gm=gradeMap(a);rows.sort((x,y)=>num(gm.get(shopKey(y))?.relative)-num(gm.get(shopKey(x))?.relative));}if(state.shopSort==='area')rows.sort((x,y)=>num(observedUnit(y)?.areaM2,-1)-num(observedUnit(x)?.areaM2,-1));if(state.shopSort==='name')rows.sort((x,y)=>shopName(x).localeCompare(shopName(y)));return rows;}
