  function intelItem(r,number=null){const historyAllowed=account()?.kind!=='company'||String(state.data?.identity?.companyId)===String(account()?.id);const values=[['Cost/min',moneyExact(r.costPerMin)],['Sales/min',r.salesPerMin?.toFixed(2)??'—'],['Wages/min',moneyExact(r.wagePerMin)],['Customers/min',r.customersPerMin?.toFixed(2)??'—'],['Basket units',r.basketUnits?.toFixed(2)??'—'],['Checkout utilization',r.registerBusy==null?'—':r.registerBusy.toFixed(1)+'%'],['Busyness',r.footTraffic?.toFixed(2)??'—'],['Wealth',r.wealth?.toFixed(2)??'—'],['Game appeal',r.appealGrade?.toFixed(1)??'—'],['Recent revenue/day',moneyExact(r.history?.recent.revenue)],['Recent units/day',r.history?.recent.units?.toFixed(1)??'—']];return `<div class="item"><div class="itemTop"><div><h4>${esc(number===null?r.name:'Gross '+number+' · '+r.name)}</h4><div class="meta">${esc(r.areaId||'Area unknown')} · building ${esc(r.buildingRef||'—')} · unit ${esc(r.unitKey||'—')}</div></div><div class="money">${moneyExact(r.grossPerMin)}/min<div class="tiny muted">game net ${moneyExact(r.gameNetPerMin)}/min</div></div></div><div class="detailGrid">${values.map(([k,v])=>`<div><span>${esc(k)}</span><b>${esc(v)}</b></div>`).join('')}</div><div class="actions"><button class="btn intelHistory" data-shop-id="${esc(r.id)}" ${historyAllowed?'':'disabled title="Pilot this company to request fresh history"'}>View history</button><button class="btn findProducts" data-shop-id="${esc(r.id)}">Products</button><button class="btn intelDetail" data-shop-id="${esc(r.id)}">${state.intelDetail===r.id?'Hide':'Details'}</button></div>${state.intelDetail===r.id?intelHistory(r):''}</div>`;}
