  function renderComparison(a){const tabs=`<div class="section card"><div class="actions"><button class="btn compareSubview ${state.compareSubview==='compare'?'primary':''}" data-view="compare">Shop Comparison</button><button class="btn compareSubview ${state.compareSubview==='trends'?'primary':''}" data-view="trends">Trend Alerts</button></div></div>`;if(state.compareSubview==='trends')return tabs+renderTrendAlerts(a);const rows=intelRows(a).map(r=>({...r,recentRevenue:r.history?.recent.revenue??null,recentUnits:r.history?.recent.units??null})),keys=[['grossPerMin','Gross/min'],['gameNetPerMin','Game net/min'],['customersPerMin','Customers/min'],['basketUnits','Basket units'],['footTraffic','Busyness'],['wealth','Wealth'],['appealGrade','Appeal'],['recentRevenue','Recent revenue'],['recentUnits','Recent units']],sorted=CRCCIntel.sort(rows,state.intelSort),page=Math.min(state.intelPage,Math.max(0,Math.ceil(rows.length/40)-1));state.intelPage=page;return tabs+renderProductFinder(a,rows)+`<div class="section card"><div class="sectionTitle">Shop comparison · ${rows.length} shops</div><div class="tiny muted">Structured game account rows. Game net requires gross, cost and wages. ${rows.filter(r=>r.history).length} histories cached.</div><select class="field" id="intelSort">${keys.map(([k,label])=>`<option value="${k}" ${state.intelSort===k?'selected':''}>${label} ↓</option>`).join('')}</select>${intelPager(page,rows.length)}</div><div class="section list">${sorted.slice(page*40,page*40+40).map(r=>intelItem(r)).join('')||'<div class="empty">No shops reported.</div>'}</div>`;}

