    for(const [id,key] of [['socialText','text'],['socialAuthor','author']]){const el=get(id);if(el)el.oninput=()=>{state.socialFilters[key]=el.value;const start=el.selectionStart;render();const replacement=get(id);replacement?.focus();replacement?.setSelectionRange(start,start);};}
    for(const [id,key] of [['socialReply','hasReply'],['socialDeleted','includeDeleted']]){const el=get(id);if(el)el.onchange=()=>{state.socialFilters[key]=el.checked;render();};}
