    const log=state.transactionLog&&String(state.transactionLog.companyId)===String(company.id)&&String(state.transactionLog.ownerPersonalId)===String(identity.personalId)?state.transactionLog:null;
    const f=state.transactionFilters,rows=log?CRCCTransactions.filter(log.rows,f):[],pageSize=60,pages=Math.max(1,Math.ceil(rows.length/pageSize)),page=Math.min(state.transactionPage,pages-1),shown=rows.slice(page*pageSize,(page+1)*pageSize);
    const kinds=[...new Set((log?.rows||[]).map(r=>r.kind))].sort();
    const input=(key,label,type='text')=>'<label class="tiny muted">'+label+' <input class="field txFilter" data-key="'+key+'" type="'+type+'" value="'+esc(f[key]??'')+'" style="width:'+(type==='date'?'130':'105')+'px"></label>';
    const sum=rows.reduce((n,r)=>n+r.amount,0),reviewCount=rows.filter(r=>CRCCTransactions.review(r,f.threshold)).length;
    return '<div class="card"><div class="sectionTitle">Company transaction log</div><div class="tiny muted">Individual entries from CapitalRift bank accounts. New entries are retained while this extension observes the company. The game may return only a limited recent window. Daily income-history buckets are not individual transactions.</div>'+
      '<div class="toolbar"><button class="btn primary" id="txRefresh">Refresh game data</button><button class="btn" id="txExport" '+(!rows.length?'disabled':'')+'>Export filtered CSV</button></div>'+
      '<div class="tiny muted">Company '+esc(company.name||company.id)+' · '+(log?.observedAt?'Last bank observation '+esc(new Date(log.observedAt).toLocaleString()):'No bank entries observed yet')+' · '+(log?.rows?.length||0).toLocaleString()+' retained · '+(log?.bankCount||0)+' accounts</div>'+
      '<div class="status">Review flags mark selected outflow types or amounts above your threshold. They are leads to inspect, not proof of fraud. Actor is shown only when CapitalRift names the initiator. A recipient is not an actor.</div>'+
      '<div class="toolbar" style="flex-wrap:wrap">'+input('query','Search')+input('actor','Actor')+input('minAmount','Min $','number')+input('threshold','Review ≥ $','number')+'</div>'+
      '<div class="toolbar" style="flex-wrap:wrap">'+input('from','From','date')+input('to','To','date')+'<label class="tiny muted">Kind <select class="field" id="txKind"><option value="">All</option>'+kinds.map(k=>'<option value="'+esc(k)+'" '+(f.kind===k?'selected':'')+'>'+esc(k)+'</option>').join('')+'</select></label><label class="tiny muted"><input id="txOutflows" type="checkbox" '+(f.outflowsOnly?'checked':'')+'> Outflows</label><label class="tiny muted"><input id="txReview" type="checkbox" '+(f.reviewOnly?'checked':'')+'> Review flags</label></div>'+
      '<div class="tiny muted">'+rows.length.toLocaleString()+' matching · '+reviewCount+' review flags · net '+moneyExact(sum)+(state.transactionMessage?' · '+esc(state.transactionMessage):'')+'</div></div>'+
      '<div class="list">'+shown.map(r=>'<div class="item"><div class="itemTop"><div><h4>'+esc(r.description)+'</h4><div class="meta">'+esc(new Date(r.ts).toLocaleString())+' · '+esc(r.kind)+' · '+esc((r.bankNames||[]).join(', ')||'Bank unknown')+'</div><div class="meta">Actor: '+esc(r.actorName||r.actorId||'Unknown (not reported)')+(r.recipient?' · Recipient: '+esc(r.recipient):'')+' · ID '+esc(r.gameId||r.id)+'</div></div><div class="money '+(r.amount<0?'red':'green')+'">'+(r.amount>=0?'+':'')+moneyExact(r.amount)+(CRCCTransactions.review(r,f.threshold)?'<div class="tiny yellow">Review</div>':'')+'</div></div></div>').join('')+(shown.length?'':'<div class="empty">No individual bank entries match. Refresh while piloting this company, or widen the filters.</div>')+'</div>'+
      '<div class="actions"><button class="btn" id="txPrev" '+(!page?'disabled':'')+'>Previous</button><span class="tiny muted">Page '+(page+1)+' / '+pages+'</span><button class="btn" id="txNext" '+(page+1>=pages?'disabled':'')+'>Next</button></div>';
