    const filter=state.transactionFilters,reset=()=>{state.transactionPage=0;render();};
    $$('.txFilter',shadow).forEach(el=>el.onchange=()=>{filter[el.dataset.key]=el.value;reset();});
    const kind=$('#txKind',shadow);if(kind)kind.onchange=()=>{filter.kind=kind.value;reset();};
