  function renderHistory(){const rows=historyRows(),scopeKey=state.scope,vals=rows.map(r=>r[scopeKey]).filter(Boolean),nw=vals.map(x=>x.netWorth),net=vals.map(x=>x.netPerMin),gross=vals.map(x=>x.shopGross),delta=(a)=>a.length>1?a.at(-1)-a[0]:0;return`<div class="toolbar"><button class="btn historyRange ${state.historyRange==='24h'?'primary':''}" data-range="24h">24h</button><button class="btn historyRange ${state.historyRange==='7d'?'primary':''}" data-range="7d">7d</button><button class="btn historyRange ${state.historyRange==='30d'?'primary':''}" data-range="30d">30d</button></div><div class="status">One Capital Rift game day = one real hour. The extension stores 5-minute snapshots plus one hourly game-day snapshot for longer trends.</div><div class="hero section">${metric('Snapshots',String(vals.length))}${metric('Net-worth change',(delta(nw)>=0?'+':'')+money(delta(nw)),delta(nw)>=0?'green':'red')}${metric('Income change',(delta(net)>=0?'+':'')+moneyExact(delta(net))+'/min',delta(net)>=0?'green':'red')}${metric('Shop gross change',(delta(gross)>=0?'+':'')+moneyExact(delta(gross))+'/min',delta(gross)>=0?'green':'red')}</div><div class="section card"><div class="sectionTitle">Net worth trend</div>${sparkline(nw)}</div><div class="section card"><div class="sectionTitle">Net income / min trend</div>${sparkline(net)}</div><div class="section card"><div class="sectionTitle">Shop gross / min trend</div>${sparkline(gross)}</div>${cashflowSection(account())}`;}

