  async function resolveLocation(row,quiet=false){
    if(!row)return null;
    let location=null,lookupError=null;
    if(row.ref&&/^((way|relation|node)\/)/i.test(String(row.ref))){
      const reply=await chrome.runtime.sendMessage({kind:'resolveOsmRef',ref:row.ref}).catch(e=>({ok:false,error:e.message}));
      if(reply?.ok&&reply.location){location=reply.location;state.osmRefs[String(row.ref)]=reply.location;}
      else lookupError=reply?.error||'Reference lookup failed';
    }
    const lat=validCoord(row.lat,row.lon)?row.lat:location?.lat,lon=validCoord(row.lat,row.lon)?row.lon:location?.lon;
    if((!location?.city||!location?.country)&&validCoord(lat,lon)){
      const reply=await chrome.runtime.sendMessage({kind:'reverseGeocode',lat,lon}).catch(e=>({ok:false,error:e.message}));
      if(reply?.ok&&reply.location){location={...reply.location,...Object.fromEntries(Object.entries(location||{}).filter(([,v])=>v!=null&&v!==''))};state.geo[geoKey(lat,lon)]=location;if(row.ref&&state.osmRefs[String(row.ref)])state.osmRefs[String(row.ref)]=location;}
      else lookupError=reply?.error||lookupError;
    }
    if(location?.city||location?.country){if(!quiet)render();return location;}
    if(!quiet)toast(lookupError||'City and country are unavailable for this property. Open its game location to capture coordinates.');
    return null;
  }
  function expectedAccount(){const a=account();return a?{kind:state.scope,id:a.id}:null;}
  function tpCoords(lat,lon,label,guard=true){if(!validCoord(lat,lon)){toast('No verified map location is available yet. Use the game eye button first.');return;}const id='nav-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2);window.postMessage({__crccCommand:true,kind:'camera',commandId:id,lat:Number(lat),lon:Number(lon),zoom:420,expectedAccount:guard?expectedAccount():null},'*');toast(`Opening ${label||'location'}…`);const timer=setTimeout(()=>{commandWaiters.delete(id);toast('Camera command timed out. Reload the game tab once and retry.');},4000);commandWaiters.set(id,{timer});}
  function beginLearnNav(type,row){const a=account();if(!a)return;const entityKey=type==='shop'?shopNavKey(row):propertyKey(row);pendingNativeFocus={accountId:a.id,entityKey,label:type==='shop'?shopName(row):(row.label||'Property'),buildingRef:row.buildingRef??row.ref??null,at:Date.now(),manual:true};toast(`Learning ${pendingNativeFocus.label}: click Capital Rift’s eye/focus icon for this exact ${type}.`);}
