  async function autoResolveProperties(rows){
    const pending=rows.filter(r=>{const loc=locationFor(r.lat,r.lon,r.city,r.country,r.state);return!(loc?.city&&loc?.country);});
    if(!pending.length){toast('All displayed properties with available locations are resolved.');return;}
    const start=state.locationCursor%pending.length,size=Math.min(12,pending.length),batch=[...pending.slice(start,start+size),...pending.slice(0,Math.max(0,start+size-pending.length))];
    state.locationCursor+=batch.length;let done=0;for(const row of batch){if(await resolveLocation(row,true))done++;}
    render();toast(`Resolved ${done}/${batch.length} locations. Press again to continue through unresolved properties.`);
  }
