        try{return await chrome.runtime.sendMessage({kind:'renameShop',shop:x.shop,newName:x.newName,scope:scope?.split(':')[0],accountId:scope?.split(':').slice(1).join(':')});}
        catch(e){return{ok:false,error:e.message};}
